CREATE OR REPLACE FUNCTION public.canonical_follow_topic(p_topic text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_topic text := btrim(coalesce(p_topic, ''));
  v_label text;
begin
  if v_topic = '' then return ''; end if;

  if v_topic like 'category:%' then
    v_topic := 'cat:' || substr(v_topic, 10);
  elsif v_topic ~ '^num_[0-9]+$' then
    v_topic := 'number:' || substr(v_topic, 5);
  elsif v_topic = 'els' then
    v_topic := 'codes:new';
  elsif v_topic in ('orgeula:new', 'or-geula', 'channel:orgeula') then
    v_topic := 'channel:or-geula';
  end if;

  if v_topic like 'cat:%' then
    v_label := substr(v_topic, 5);
    v_label := replace(replace(replace(v_label, '"', '״'), '“', '״'), '”', '״');
    return 'cat:' || case when v_label = 'רמזי הגאולה' then 'רמזים חזקים' else v_label end;
  end if;

  return v_topic;
end
$function$
;
CREATE OR REPLACE FUNCTION public.follow_topic_aliases(p_topic text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_topic text := public.canonical_follow_topic(p_topic);
  v_label text;
  v_straight text;
begin
  if v_topic = '' then return array[]::text[]; end if;

  if v_topic like 'cat:%' then
    v_label := substr(v_topic, 5);
    v_straight := replace(v_label, '״', '"');
    return array(
      select distinct x
      from unnest(array[
        v_topic,
        'cat:' || v_straight,
        'category:' || v_label,
        'category:' || v_straight,
        case when v_label = 'רמזים חזקים' then 'cat:רמזי הגאולה' end,
        case when v_label = 'רמזים חזקים' then 'category:רמזי הגאולה' end
      ]) as x
      where x <> ''
    );
  end if;

  if v_topic like 'number:%' then
    v_label := substr(v_topic, 8);
    return array[v_topic, 'num_' || v_label];
  end if;

  if v_topic = 'codes:new' then
    return array['codes:new', 'els'];
  end if;

  if v_topic = 'channel:or-geula' then
    return array['channel:or-geula', 'orgeula:new', 'or-geula', 'channel:orgeula'];
  end if;

  return array[v_topic];
end
$function$
;
CREATE OR REPLACE FUNCTION public.canonical_follow_subject(p_entity_type text, p_stable_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  v_type text := lower(btrim(coalesce(p_entity_type, '')));
  v_id text := btrim(coalesce(p_stable_id, ''));
begin
  if v_type = '' or v_id = '' then return ''; end if;

  return case v_type
    when 'number'         then public.canonical_follow_topic('number:' || v_id)
    when 'author'         then public.canonical_follow_topic('author:' || v_id)
    when 'category'       then public.canonical_follow_topic('cat:' || v_id)
    when 'series'         then case when v_id in ('mah-kore-habora', 'dimension-five', 'sod-hashmal') then 'series:' || v_id else '' end
    when 'cipher_feed'    then 'codes:new'
    when 'reality_stream' then 'stream:reality'
    when 'media_channel'  then case
      when lower(replace(v_id, '_', '-')) in ('or-geula', 'orgeula') then 'channel:or-geula'
      else public.canonical_follow_topic('channel:' || v_id)
    end
    when 'channel'        then case
      when lower(replace(v_id, '_', '-')) in ('or-geula', 'orgeula') then 'channel:or-geula'
      else public.canonical_follow_topic('channel:' || v_id)
    end
    else ''
  end;
end
$function$
;

-- Internal pure compatibility matcher; not an exposed entity registry or RPC.
create function public.post_content_series_keys_v1(p_categories text[], p_tags text[], p_author text)
returns text[] language sql immutable set search_path = ''
as $series$
  select coalesce(array_agg(series_key order by series_key) filter(where matches), '{}'::text[])
  from (values
    ('mah-kore-habora', ('מה קורה הבורא' = any(coalesce(p_tags, '{}'::text[]))) and coalesce(p_author, '') = 'אלון לוי'),
    ('dimension-five', ('מימד חמש' = any(coalesce(p_categories, '{}'::text[]))) and coalesce(p_author, '') = 'בדרך לנצח'),
    ('sod-hashmal', ('סוד החשמל' = any(coalesce(p_categories, '{}'::text[])) or 'סוד החשמל' = any(coalesce(p_tags, '{}'::text[]))))
  ) as approved(series_key, matches);
$series$;
revoke all on function public.post_content_series_keys_v1(text[],text[],text) from public, anon, authenticated;

create or replace function public.notify_on_post_publish()
returns trigger language plpgsql security definer set search_path = public
as $function$
declare c text; s text;
begin
  -- Taxonomy/author/title edits never become new publication events. Only an
  -- explicit transition out of draft/forum can publish an existing recent row.
  if TG_OP = 'UPDATE' and not (coalesce(OLD.tags, '{}'::text[]) && array['טיוטה','פורום']) then return NEW; end if;
  if coalesce(NEW.tags, '{}'::text[]) && array['טיוטה','פורום'] then return NEW; end if;
  if nullif(btrim(NEW.slug), '') is null then return NEW; end if;
  if coalesce(NEW.date, now()) < now() - interval '2 hours' then return NEW; end if;
  if NEW.categories is not null then
    foreach c in array NEW.categories loop
      if c is not null and btrim(c) <> '' then
        perform public.dispatch('category', c, 'post_new', NEW.id::text,
          'פוסט חדש ב' || c, NEW.title, '/' || NEW.slug);
      end if;
    end loop;
  end if;
  if NEW.author is not null and btrim(NEW.author) <> '' and NEW.author <> 'המערכת' then
    perform public.dispatch('author', NEW.author, 'post_new', NEW.id::text,
      'פוסט חדש מאת ' || NEW.author, NEW.title, '/' || NEW.slug);
  end if;
  foreach s in array public.post_content_series_keys_v1(NEW.categories, NEW.tags, NEW.author) loop
    perform public.dispatch('series', s, 'post_new', NEW.id::text,
      'פרסום חדש בסדרה', NEW.title, '/' || NEW.slug);
  end loop;
  return NEW;
end
$function$;

-- Reuse the single trigger/dispatcher and its existing recipient+event dedupe.
drop trigger if exists trg_posts_notify on public.posts;
create trigger trg_posts_notify after insert or update of tags on public.posts
for each row execute function public.notify_on_post_publish();
commit;
